// Entrada: { doc_id, add_tags?: [nombres], remove_tags?: [nombres], fields?: {nombre: valor}, note?: texto }
// Salida: una petición HTTP por operación, siempre por bulk_edit (toca solo lo indicado) y notes.
const req = $('Entrada').first().json;
const base = $env.PAPERLESS_BASE_URL;
const tags = $('List tags').first().json.results || [];
const fields = $('List custom fields').first().json.results || [];
const find = (list, kind, n) => {
  const x = list.find(o => o.name.toLowerCase() === String(n).toLowerCase());
  if (!x) throw new Error(`${kind} no existe en Paperless: ${n} (correr paperless_setup.py)`);
  return x;
};
const docId = Number(req.doc_id);
if (!docId) throw new Error('doc_id requerido');
const bulk = (method, parameters) => ({ json: { method: 'POST', url: `${base}/api/documents/bulk_edit/`,
  body: { documents: [docId], method, parameters } } });
const out = [];
const add = (req.add_tags || []).map(n => find(tags, 'Etiqueta', n).id);
const remove = (req.remove_tags || []).map(n => find(tags, 'Etiqueta', n).id);
// Etiquetas primero: la de estado evita que las escrituras siguientes vuelvan a disparar el workflow nativo.
if (add.length || remove.length) out.push(bulk('modify_tags', { add_tags: add, remove_tags: remove }));
const values = {};
for (const [name, raw] of Object.entries(req.fields || {})) {
  if (raw === null || raw === undefined || raw === '') continue;
  const f = find(fields, 'Campo', name);
  let value = raw;
  if (f.data_type === 'monetary') {
    const cur = (f.extra_data && f.extra_data.default_currency) || 'USD';
    const num = typeof raw === 'number' ? raw : Number(String(raw).replace(/[^0-9.,-]/g, '').replace(',', '.'));
    value = /^[A-Z]{3}/.test(String(raw)) ? String(raw) : (isNaN(num) ? null : cur + num.toFixed(2));
  } else if (f.data_type === 'string') {
    value = String(raw).slice(0, 128);
  } else if (f.data_type === 'integer') {
    value = parseInt(raw, 10);
  }
  if (value !== null && !(typeof value === 'number' && isNaN(value))) values[f.id] = value;
}
if (Object.keys(values).length) out.push(bulk('modify_custom_fields', { add_custom_fields: values, remove_custom_fields: [] }));
if (req.note) out.push({ json: { method: 'POST', url: `${base}/api/documents/${docId}/notes/`, body: { note: String(req.note) } } });
return out;
